{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case field")
    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError("invalid case field type")
    if any(not isinstance(symbol, str) for symbol in required_symbols):
        raise ValueError("required_symbols must contain strings")
    if len(set(required_symbols)) != len(required_symbols):
        raise ValueError("duplicate required symbol")

    by_id = {}
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("node must be an object")
        for field in ("id", "parent", "symbol", "depth", "removable", "utility"):
            if field not in node:
                raise ValueError("missing required node field")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        utility = node["utility"]
        if not isinstance(node_id, str) or not node_id:
            raise ValueError("invalid node id")
        if node_id in by_id:
            raise ValueError("duplicate node id")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("invalid parent")
        if not isinstance(symbol, str):
            raise ValueError("invalid symbol")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("invalid depth")
        if not isinstance(node["removable"], bool):
            raise ValueError("invalid removable flag")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError("invalid utility")
        by_id[node_id] = node

    if not by_id:
        raise ValueError("tree must not be empty")
    roots = [node for node in nodes if node["parent"] is None]
    if len(roots) != 1 or roots[0]["depth"] != 0:
        raise ValueError("invalid root")
    root_id = roots[0]["id"]

    children = {node_id: [] for node_id in by_id}
    for node in nodes:
        parent = node["parent"]
        if parent is None:
            continue
        if parent not in by_id or parent == node["id"]:
            raise ValueError("invalid parent reference")
        if node["depth"] != by_id[parent]["depth"] + 1:
            raise ValueError("inconsistent depth")
        children[parent].append(node["id"])

    visited = set()
    pending = [root_id]
    while pending:
        node_id = pending.pop()
        if node_id in visited:
            raise ValueError("invalid tree structure")
        visited.add(node_id)
        pending.extend(children[node_id])
    if len(visited) != len(by_id):
        raise ValueError("tree is disconnected or cyclic")

    symbol_counts = {}
    for node in nodes:
        symbol = node["symbol"]
        symbol_counts[symbol] = symbol_counts.get(symbol, 0) + 1
    if any(symbol_counts.get(symbol, 0) == 0 for symbol in required_symbols):
        raise ValueError("required symbol is absent")

    retained = set(by_id)
    removed = []
    ordered_ids = sorted(by_id, key=lambda node_id: (-by_id[node_id]["depth"], node_id))
    required_set = set(required_symbols)
    for node_id in ordered_ids:
        node = by_id[node_id]
        if node_id == root_id or not node["removable"]:
            continue
        if node["symbol"] in required_set:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue
        symbol = node["symbol"]
        if symbol in required_set and symbol_counts[symbol] <= 1:
            continue
        retained.remove(node_id)
        removed.append(node_id)
        symbol_counts[symbol] -= 1

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained),
    }
"}
